def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    frames = {}
    for r in range(h):
        for c in range(w):
            v = g[r][c]
            if v == 0:
                continue
            frames.setdefault(v, []).append((r, c))
    # Locate rectangular outlines and assign the sparse marker colors:
    # the smallest outline takes the rare marker, and the other outlines
    # take the remaining marker colors in increasing frequency order.
    rects = []
    for color, pts in frames.items():
        rs = [r for r, c in pts]
        cs = [c for r, c in pts]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        if r1-r0 >= 2 and c1-c0 >= 2 and len(pts) == 2*(r1-r0+1)+2*(c1-c0-1):
            if all(g[r0][c] == color and g[r1][c] == color for c in range(c0,c1+1)) and \
               all(g[r][c0] == color and g[r][c1] == color for r in range(r0,r1+1)):
                rects.append((color, r0, r1, c0, c1))
    nonframe = {}
    for r in range(h):
        for c in range(w):
            v = g[r][c]
            if v and not any(v == fc and r0 <= r <= r1 and c0 <= c <= c1
                             for fc, r0, r1, c0, c1 in rects):
                nonframe[v] = nonframe.get(v, 0) + 1
    markers = sorted(nonframe, key=lambda x: nonframe[x])
    rects.sort(key=lambda x: (x[2]-x[1]-1)*(x[4]-x[3]-1))
    # Use marker colors ordered by abundance for increasing frame area.
    for i, (_, r0, r1, c0, c1) in enumerate(rects):
        if not markers:
            continue
        color = markers[min(i, len(markers)-1)]
        for r in range(r0+1, r1):
            for c in range(c0+1, c1):
                g[r][c] = color if (r-r0-1 + c-c0-1) % 2 == 0 else 0
    # Clear non-frame speckles.
    for r in range(h):
        for c in range(w):
            if g[r][c] and not any(r0 <= r <= r1 and c0 <= c <= c1
                                   for _, r0, r1, c0, c1 in rects):
                g[r][c] = 0
    return g
